---@class Quality
local Quality = T(Global, "Quality")

function Quality:onTick()
	Quality:checkReport()
end

local LastReportPerformanceTime = 0

function Quality:checkReport()
	if os.time() - LastReportPerformanceTime < 60 then return end
	self:performanceReport()
end

function Quality:performanceReport()

	if PlayerManager:getClientPlayer() == nil then
		return
	end

	local fpsInfo = PerformanceStatistics.GetFpsInfo() or {}
	local netPingInfo = PerformanceStatistics.GetNetPingInfo() or {}
	local logicPingInfo = PerformanceStatistics.GetLogicPingInfo() or {}
	if not next(fpsInfo) and not next(netPingInfo) and not next(logicPingInfo) then return end

	PlayerManager:getClientPlayer():sendPacket({
		pid = "PerformanceReport",
		fps = fpsInfo,
		netPing = netPingInfo,
		logicPing = logicPingInfo
	})
	LastReportPerformanceTime = os.time()
end

function Quality:run()
	LuaTimer:scheduleTimer(function()
		self:onTick()
	end, 1000)
end

Quality:run()
